BEGIN;

CREATE TABLE IF NOT EXISTS hotels (
    hotel_id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    city VARCHAR(50) NOT NULL,
    district VARCHAR(100),
    address VARCHAR(255),
    price INTEGER NOT NULL CHECK (price >= 0),
    rating NUMERIC(2,1) CHECK (rating >= 0 AND rating <= 5),
    review_count INTEGER NOT NULL DEFAULT 0 CHECK (review_count >= 0),
    hotel_grade SMALLINT CHECK (hotel_grade BETWEEN 1 AND 5),
    room_type VARCHAR(50),
    breakfast_included BOOLEAN NOT NULL DEFAULT FALSE,
    parking BOOLEAN NOT NULL DEFAULT FALSE,
    wifi BOOLEAN NOT NULL DEFAULT FALSE,
    pool BOOLEAN NOT NULL DEFAULT FALSE,
    description TEXT
);

CREATE INDEX IF NOT EXISTS idx_hotels_city ON hotels(city);
CREATE INDEX IF NOT EXISTS idx_hotels_price ON hotels(price);
CREATE INDEX IF NOT EXISTS idx_hotels_rating ON hotels(rating);
CREATE INDEX IF NOT EXISTS idx_hotels_grade ON hotels(hotel_grade);

INSERT INTO hotels (
    hotel_id,
